"""Generated by deploy/build_bundle.py from contracts/liveness.py and contracts/will.py.
Comments removed to keep the deploy small; read them in those files."""
ALIVE = 'alive'
SILENT = 'silent'
UNREACHABLE = 'unreachable'
MIN_SILENT_RUNS = 3
SILENCE_FRESH_SECONDS = 7 * 24 * 3600
_MAX_HOST = 100
_MAX_PATH = 200
_MAX_MARKER = 200
_MAX_NAME = 40

def valid_host(host: str) -> bool:
    h = (host or '').strip().lower()
    if not h or len(h) > _MAX_HOST or h.startswith('.') or h.endswith('.') or ('..' in h):
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in h

def valid_path(path: str) -> bool:
    p = (path or '').strip()
    if not p.startswith('/') or len(p) > _MAX_PATH:
        return False
    if '..' in p or '://' in p or '?' in p or ('#' in p) or ('//' in p):
        return False
    return True

def valid_name(name: str) -> bool:
    n = (name or '').strip().lower()
    if not n or len(n) > _MAX_NAME:
        return False
    for ch in n:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-_'):
            return False
    return True

def valid_marker(marker: str) -> bool:
    m = (marker or '').strip()
    if not m or len(m) > _MAX_MARKER:
        return False
    return '\n' not in m and '\r' not in m

def marker_present(body: str, marker: str) -> bool:
    if not marker:
        return False
    return marker.strip() in (body or '')

def url_for(host: str, path: str) -> str:
    return 'https://' + host.strip().lower() + path.strip()

def days_between(earlier_seconds, later_seconds):
    if earlier_seconds is None or later_seconds is None:
        return None
    if later_seconds < earlier_seconds:
        return 0
    return (later_seconds - earlier_seconds) // 86400

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *
STATE_HELD = 'held'
STATE_PAID = 'paid'
STATE_CANCELLED = 'cancelled'
MIN_SILENCE_DAYS = 30
MAX_SILENCE_DAYS = 3650

@gl.storage.allow
@dataclass
class Will:
    owner: Address
    successor: Address
    amount: u256
    pulse: Address
    pulse_id: str
    silence_days: u256
    written_at: str
    state: str
    decided_at: str
    reason: str

class WillContract(gl.contract.Contract):
    pulse: Address
    probate: Address
    founder: Address
    wills: gl.storage.TreeMap[str, Will]
    will_ids: gl.storage.DynArray[str]
    committed: u256

    def __init__(self, pulse: str):
        self.pulse = _address(pulse)
        self.probate = _zero()
        self.founder = gl.message.sender_address
        self.committed = 0

    @gl.public.write
    def bind_probate(self, probate: str) -> dict:
        if gl.message.sender_address.as_hex.lower() != self.founder.as_hex.lower():
            raise gl.vm.UserError('only whoever deployed this may name the court')
        if self.probate.as_hex.lower() != '0x' + '00' * 20:
            raise gl.vm.UserError('the court is already named and cannot be changed')
        at = _address(probate)
        if at.as_hex.lower() == '0x' + '00' * 20:
            raise gl.vm.UserError('name a real contract')
        self.probate = at
        return self.settings()

    @gl.public.write.payable
    def write(self, pulse_id: str, successor: str, silence_days: int) -> dict:
        amount = gl.message.value
        if amount <= 0:
            raise gl.vm.UserError('send the deposit with this call')
        days = int(silence_days)
        if days < MIN_SILENCE_DAYS or days > MAX_SILENCE_DAYS:
            raise gl.vm.UserError(f'silence must be between {MIN_SILENCE_DAYS} and {MAX_SILENCE_DAYS} days')
        at = self.pulse
        key = pulse_id.strip().lower()
        record = gl.contract.get_at(at).view().get_pulse(key)
        owner = gl.message.sender_address
        if str(record['owner']).lower() != owner.as_hex.lower():
            raise gl.vm.UserError('that pulse belongs to somebody else')
        heir = _address(successor)
        if heir.as_hex.lower() == '0x' + '00' * 20:
            raise gl.vm.UserError('a payout to the zero address would burn the deposit')
        if heir.as_hex.lower() == owner.as_hex.lower():
            raise gl.vm.UserError('name somebody other than yourself')
        will_id = owner.as_hex.lower() + '|' + key
        if will_id in self.wills and self.wills[will_id].state == STATE_HELD:
            raise gl.vm.UserError('that pulse already has a will; cancel it first')
        first_time = will_id not in self.wills
        self.wills[will_id] = Will(owner=owner, successor=heir, amount=amount, pulse=at, pulse_id=key, silence_days=days, written_at=_stamp(), state=STATE_HELD, decided_at='', reason='')
        if first_time:
            self.will_ids.append(will_id)
        self.committed = self.committed + amount
        return _as_dict(will_id, self.wills[will_id])

    @gl.public.write.payable
    def top_up(self, will_id: str) -> dict:
        key = will_id.strip().lower()
        will = self._held(key)
        if will.owner.as_hex.lower() != gl.message.sender_address.as_hex.lower():
            raise gl.vm.UserError('only the owner may add to a will')
        amount = gl.message.value
        if amount <= 0:
            raise gl.vm.UserError('send something with this call')
        will.amount = will.amount + amount
        self.wills[key] = will
        self.committed = self.committed + amount
        return _as_dict(key, will)

    @gl.public.write
    def cancel(self, will_id: str) -> dict:
        key = will_id.strip().lower()
        will = self._held(key)
        if will.owner.as_hex.lower() != gl.message.sender_address.as_hex.lower():
            raise gl.vm.UserError('only the owner may cancel a will')
        amount = int(will.amount)
        will.state = STATE_CANCELLED
        will.decided_at = _stamp()
        will.reason = 'the owner cancelled it'
        self.wills[key] = will
        self.committed = self.committed - amount
        _pay(will.owner, amount)
        return _as_dict(key, will)

    @gl.public.write
    def execute(self, probate_id: str, will_id: str) -> dict:
        key = will_id.strip().lower()
        will = self._held(key)
        if self.probate.as_hex.lower() == '0x' + '00' * 20:
            raise gl.vm.UserError('no court has been named yet')
        verdict = gl.contract.get_at(self.probate).view().verdict(probate_id.strip().lower())
        if str(verdict['will_id']).lower() != key:
            raise gl.vm.UserError('that probate is about a different will')
        if str(verdict['owner']).lower() != will.owner.as_hex.lower():
            raise gl.vm.UserError('that probate names a different owner')
        if str(verdict['pulse_id']).lower() != will.pulse_id:
            raise gl.vm.UserError('that probate watches a different pulse')
        state = str(verdict['state'])
        if state != 'ripe':
            return self._undecided(key, will, 'the probate is ' + state + ': ' + str(verdict['reason']))
        record = gl.contract.get_at(will.pulse).view().get_pulse(will.pulse_id)
        seen = epoch_seconds(str(record['last_alive']))
        opened = epoch_seconds(str(verdict['opened_at']))
        if seen is None or opened is None:
            return self._undecided(key, will, 'a timestamp on this pulse could not be read')
        if seen > opened:
            return self._undecided(key, will, 'the owner has been seen since probate opened, so nothing is owed')
        runs = int(str(record['silent_runs']))
        if runs < MIN_SILENT_RUNS:
            return self._undecided(key, will, f'only {runs} observations found the marker gone, and {MIN_SILENT_RUNS} are required')
        age = int(str(record['silence_age_seconds']))
        if age < 0:
            return self._undecided(key, will, 'no observation has ever found the marker gone')
        if age > SILENCE_FRESH_SECONDS:
            return self._undecided(key, will, f'the last confirmed silence is {age} seconds old; observe it again')
        amount = int(will.amount)
        will.state = STATE_PAID
        will.decided_at = _stamp()
        will.reason = 'the silence ran and nobody answered'
        self.wills[key] = will
        self.committed = self.committed - amount
        _pay(will.successor, amount)
        return _as_dict(key, will)

    @gl.public.view
    def settings(self) -> dict:
        return {'pulse': self.pulse.as_hex, 'probate': self.probate.as_hex, 'founder': self.founder.as_hex}

    @gl.public.view
    def get_will(self, will_id: str) -> dict:
        key = will_id.strip().lower()
        if key not in self.wills:
            raise gl.vm.UserError('no such will: ' + key)
        return _as_dict(key, self.wills[key])

    @gl.public.view
    def will_list(self) -> list:
        return [w for w in self.will_ids]

    @gl.public.view
    def reserves(self) -> dict:
        return {'committed': str(self.committed)}

    @gl.public.view
    def terms(self) -> dict:
        return {'min_silence_days': str(MIN_SILENCE_DAYS), 'max_silence_days': str(MAX_SILENCE_DAYS), 'runs_required': str(MIN_SILENT_RUNS), 'silence_fresh_for_seconds': str(SILENCE_FRESH_SECONDS)}

    def _held(self, key: str) -> Will:
        if key not in self.wills:
            raise gl.vm.UserError('no such will: ' + key)
        will = self.wills[key]
        if will.state != STATE_HELD:
            raise gl.vm.UserError('that will is already ' + will.state)
        return will

    def _undecided(self, key: str, will: Will, why: str) -> dict:
        will.reason = why
        self.wills[key] = will
        return _as_dict(key, will)

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _zero() -> Address:
    return Address('0x' + '00' * 20)

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

@gl.evm.contract_interface
class _Wallet:

    class View:
        pass

    class Write:
        pass

def _pay(to: Address, amount: int) -> None:
    _Wallet(to).emit_transfer(value=amount)

def _as_dict(key: str, will: Will) -> dict:
    return {'will_id': key, 'owner': will.owner.as_hex, 'successor': will.successor.as_hex, 'amount': str(will.amount), 'pulse': will.pulse.as_hex, 'pulse_id': will.pulse_id, 'silence_days': str(will.silence_days), 'written_at': will.written_at, 'state': will.state, 'decided_at': will.decided_at, 'reason': will.reason}
